import { COPY_ONLY_CLASS, NO_COPY_CLASS } from "@hunt/copy-to-clipboard";
import { HorizontalDivider, useColorAssist } from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import React from "react";
import type { Color, SectionProps, PuzzleData } from "./datatypes";

const COLOR_TO_SHAPE: Record<Color, string> = {
  black: "●", // circle
  pink: "▲", // triangle
  yellow: "■", // square
  lightblue: "◆", // diamond
  red: "▬", // rectangle
};

const COLOR_TO_NAME: Record<Color, string> = {
  black: "black",
  pink: "pink",
  yellow: "yellow",
  lightblue: "light blue",
  red: "red",
};

const COLOR_TO_HEX_CODE: Record<Color, string> = {
  black: "#000000",
  pink: "#FFC0CB",
  yellow: "#FFFF00",
  lightblue: "#ADD8E6",
  red: "#FF0000",
};

const COLOR_LIST: Color[] = ["black", "pink", "yellow", "lightblue", "red"];

// Subcomponent to render a block of highlighted text and corresponding table
function Section({ fragments, showShapes }: SectionProps) {
  return (
    <>
      <p className={`my-5 ${NO_COPY_CLASS}`}>
        {fragments.map((fragment, idx) => (
          <React.Fragment key={idx}>
            {idx > 0 && " "}
            <span
              style={{
                backgroundColor: fragment.color,
                color: fragment.color === "black" ? "white" : "black",
              }}
            >
              {showShapes
                ? fragment.text
                    .split(" ")
                    .map((i) => i + COLOR_TO_SHAPE[fragment.color])
                    .join(" ")
                : fragment.text}
            </span>
          </React.Fragment>
        ))}
      </p>

      <table className={COPY_ONLY_CLASS}>
        <tbody>
          <tr>
            {fragments.map((fragment, fIdx) =>
              fragment.text.split(" ").map((part, pIdx) => (
                <td
                  key={`${fIdx}-${pIdx}`}
                  style={{
                    backgroundColor: fragment.color,
                    color: fragment.color === "black" ? "white" : "black",
                  }}
                >
                  {showShapes ? part + COLOR_TO_SHAPE[fragment.color] : part}
                </td>
              )),
            )}
          </tr>
        </tbody>
      </table>
    </>
  );
}

export function PuzzleComponent({ data }: PuzzleData) {
  const [colorAssistEnabled, setColorAssistEnabled] = useColorAssist();

  return (
    <>
      {/* Color assist accessibility toggle */}
      <div className={cn("flex items-center space-x-2 mb-4", NO_COPY_CLASS)}>
        <label className="flex items-center space-x-2 cursor-pointer">
          <input
            type="checkbox"
            checked={colorAssistEnabled}
            onChange={() => {
              setColorAssistEnabled(!colorAssistEnabled);
            }}
            className="h-4 w-4 rounded border-gray-300"
            aria-label="Enable color assist mode to show color legend with shapes"
          />
          <span>Show color legend</span>
        </label>
      </div>
      {/* Legend for colorblind friendly mode */}
      {colorAssistEnabled && (
        <div className="my-2">
          <div className={cn("flex flex-col gap-2", NO_COPY_CLASS)}>
            {COLOR_LIST.map((color) => (
              <div key={color} className="flex items-center gap-2">
                <div
                  className="w-4 h-4 rounded"
                  style={{ backgroundColor: color }}
                  role="img"
                  aria-label={`${COLOR_TO_NAME[color]} color sample`}
                />
                <span className="font-mono">{COLOR_TO_SHAPE[color]}</span>
                <span className="font-mono">
                  {COLOR_TO_NAME[color]} ({COLOR_TO_HEX_CODE[color]})
                </span>
              </div>
            ))}
          </div>
          <table className={COPY_ONLY_CLASS}>
            <tbody>
              {COLOR_LIST.map((color) => (
                <tr key={color}>
                  <td
                    style={{ backgroundColor: color }}
                    aria-label={`${COLOR_TO_NAME[color]} color sample`}
                  ></td>
                  <td className="font-mono">{COLOR_TO_SHAPE[color]}</td>
                  <td className="font-mono">
                    {COLOR_TO_NAME[color]} ({COLOR_TO_HEX_CODE[color]})
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {data.slice(0, -1).map((frags, idx) => (
        <React.Fragment key={idx}>
          <Section fragments={frags} showShapes={colorAssistEnabled} />
        </React.Fragment>
      ))}

      <HorizontalDivider />

      <Section
        fragments={data[data.length - 1]}
        showShapes={colorAssistEnabled}
      />
    </>
  );
}
