import React from "react";
import { createRoot } from "react-dom/client";
import { PuzzleComponent } from "./PuzzleComponent";
import type { Fragment } from "./datatypes";

const elem = document.getElementById("puzzle-root");
if (elem) {
  const puzzleData = (window as unknown as { data: Fragment[][] }).data;
  const root = createRoot(elem);
  root.render(<PuzzleComponent data={puzzleData} />);
} else {
  console.error(
    "Could not mount PuzzleComponent because #puzzle-root was nowhere to be found",
  );
}
